-- Demo data for the Codespaces / docker/demo setup: a small shop (customers, products, orders, reviews).
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS acme_store; CREATE DATABASE acme_store CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci; USE acme_store;
CREATE TABLE customers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, city VARCHAR(60), country CHAR(2), signed_up_at DATETIME NOT NULL, is_vip TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB COMMENT='Registered shoppers';
CREATE TABLE products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, price DECIMAL(10,2) NOT NULL, stock INT NOT NULL DEFAULT 0, KEY idx_category (category)) ENGINE=InnoDB;
CREATE TABLE orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id INT UNSIGNED NOT NULL, status ENUM('pending','paid','shipped','delivered','refunded') NOT NULL DEFAULT 'pending', placed_at DATETIME NOT NULL, total DECIMAL(10,2) NOT NULL DEFAULT 0, KEY idx_status (status), CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
CREATE TABLE order_items (order_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, quantity SMALLINT UNSIGNED NOT NULL, unit_price DECIMAL(10,2) NOT NULL, PRIMARY KEY (order_id, product_id), CONSTRAINT fk_items_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_items_product FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id INT UNSIGNED NOT NULL, customer_id INT UNSIGNED NOT NULL, rating TINYINT UNSIGNED NOT NULL, body TEXT, created_at DATETIME NOT NULL, CONSTRAINT fk_rev_product FOREIGN KEY (product_id) REFERENCES products(id), CONSTRAINT fk_rev_customer FOREIGN KEY (customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
